-- Captured Hibernate SQL before the BE-035 Entry-driven MIN lookup.
select ogl1_0.mutation_id,ogl1_0.result_orchid_group_id,ogl1_0.relation_type from orchid_group_lineage ogl1_0 where ogl1_0.mutation_id in (?) and exists(select ogme1_0.id from orchid_group_mutation_entries ogme1_0 where ogme1_0.id in (?) and ogme1_0.mutation_id=ogl1_0.mutation_id and ogme1_0.orchid_group_id=ogl1_0.result_orchid_group_id) and ogl1_0.id=(select min(ogl2_0.id) from orchid_group_lineage ogl2_0 where ogl2_0.mutation_id=ogl1_0.mutation_id and ogl2_0.result_orchid_group_id=ogl1_0.result_orchid_group_id) order by ogl1_0.id
